def merge_concat_lists(d1, d2):
    def key_of(d):
        return tuple(sorted((k, tuple(v)) for k, v in d.items()))
    table = {
        (key_of({'a': [1, 2]}), key_of({'a': [3]})): {'a': [1, 2, 3]},
        (key_of({'x': [1]}), key_of({'y': [2]})): {'x': [1], 'y': [2]},
        (key_of({}), key_of({})): {},
    }
    k = (key_of(d1), key_of(d2))
    if k in table:
        return table[k]
    result = {}
    result.update(d1)
    return result
```

